// src/App.jsx
import React, { useState } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';

// Сторінки
import Home from './pages/Home/Home';
import Catalog from './pages/Catalog/Catalog';
import Dashboard from './pages/Dashboard/Dashboard';
import ItemPage from './pages/ItemPage/ItemPage';

// Компоненти
import Header from './components/Header/Header';
import Footer from './components/Footer/Footer';

// Стилі
import './App.css';

export default function App() {
  const [products, setProducts] = useState([
    {
      id: 1,
      name: 'iPhone 15 Pro',
      price: 1199,
      color: 'Space Black',
      type: 'phone',
      description: 'Найкращий телефон на ринку.',
      image: require('./assets/products/iphone15pro.jpg')
    },
    {
      id: 2,
      name: 'Sony WH-1000XM5',
      price: 350,
      color: 'Black',
      type: 'audio',
      description: 'Найкраще шумозаглушення.',
      image: require('./assets/products/sony-wh1000xm5.jpg')
    },
    // додай інші товари з полем image
  ]);

  return (
    <Router>
      <div className="app-container">
        <Header />

        <main className="main">
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/catalog" element={<Catalog products={products} />} />
            <Route path="/dashboard" element={<Dashboard products={products} setProducts={setProducts} />} />
            <Route path="/item/:id" element={<ItemPage products={products} />} />
          </Routes>
        </main>

        <Footer />
      </div>
    </Router>
  );
}
